package com.example.starter.observation;

/**
 * 质量问题类别。
 */
public enum QualityCategory {

    /** 传感器异常。 */
    SENSOR_ANOMALY,

    /** 人工误操作。 */
    HUMAN_MISOPERATION,

    /** 环境干扰。 */
    ENVIRONMENTAL_INTERFERENCE
}

package com.example.starter.observation;

/**
 * 质量标记状态。
 */
public enum FlagStatus {

    /** 待复核。 */
    PENDING,

    /** 复核确认：同一版本下该类别首个有效 CONFIRMED 会扣减置信度。 */
    CONFIRMED,

    /** 复核驳回：不影响置信度。 */
    DISMISSED,

    /** 观测已产生新版本，标记失效：不可再复核，也不影响新版本。 */
    STALE
}

package com.example.starter.observation;

/**
 * 复核结论。
 */
public enum ReviewConclusion {

    /** 确认质量问题：该版本该类别首个有效确认扣减置信度 20。 */
    CONFIRMED,

    /** 驳回：不影响置信度。 */
    DISMISSED
}

package com.example.starter.observation;

/**
 * 置信度轨迹事件类型。
 */
public enum ConfidenceEventType {

    /** 观测创建：初始置信度 100。 */
    INITIAL,

    /** 复核确认生效：每个版本每个类别首次 CONFIRMED 扣减 20。 */
    CONFIRMED,

    /** 新版本生成：固化该版本继承到的置信度（不发生数值变化，仅记录版本轨迹点）。 */
    VERSION
}

