     */
    public void markStale(String flagKey) {
        jdbcTemplate.update(
                "UPDATE quality_flag SET status = 'STALE', reviewed_at = CURRENT_TIMESTAMP WHERE flag_key = ?",
                flagKey);
    }

    /**
     * 追加不可变复核记录。
     */
    public void insertReview(QualityFlagReview review) {
        jdbcTemplate.update(
                "INSERT INTO quality_flag_review (flag_key, observation_id, flag_version, review_version, "
                        + "conclusion, reason, reviewed_by, confidence_after, confidence_delta, created_at) "
                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)",
                review.flagKey(), review.observationId(), review.flagVersion(), review.reviewVersion(),
                review.conclusion().name(), review.reason(), review.reviewBy(),
                review.confidenceAfter(), review.confidenceDelta());
    }

    /**
     * 同一观测同一版本同一类别是否已存在产生扣减的有效 CONFIRMED 记录。
     */
    public boolean existsEffectiveConfirmed(String observationId, int version, QualityCategory category) {
        Integer count = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM quality_flag_review "
                        + "WHERE observation_id = ? AND flag_version = ? AND conclusion = 'CONFIRMED' "
                        + "AND category_of_review_placeholder IS NULL",
                Integer.class);
