                        + "reviewed_by, confidence_after, confidence_delta, created_at "
                        + "FROM quality_flag_review WHERE observation_id = ? ORDER BY id",
                REVIEW_MAPPER, observationId);
    }

    private String flagSelect() {
        return "SELECT flag_key, observation_id, version, category, description, submitted_by, status, "
                + "reviewed_by, review_reason, review_version, created_at, reviewed_at FROM quality_flag";
    }
}

