                "SELECT COUNT(*) FROM quality_flag_review r "
                        + "JOIN quality_flag f ON f.flag_key = r.flag_key "
                        + "WHERE r.observation_id = ? AND r.flag_version = ? AND f.category = ? "
                        + "AND r.conclusion = 'CONFIRMED' AND r.confidence_delta < 0",
                Integer.class, observationId, version, category.name());
        return count != null && count > 0;
    }

    /**
     * 查询某观测的全部标记（含各状态），按创建顺序返回。
     */
    public List<QualityFlag> findFlagsByObservation(String observationId) {
        return jdbcTemplate.query(
