    }

    /**
     * 查询某观测当前待复核标记清单。
     */
    public List<QualityFlag> findPendingByObservation(String observationId) {
        return jdbcTemplate.query(
                flagSelect() + " WHERE observation_id = ? AND status = 'PENDING' "
                        + "ORDER BY created_at, flag_key",
                FLAG_MAPPER, observationId);
    }

    /**
