package com.example.starter.observation;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.List;
import java.util.Optional;

/**
 * 观测质量标记业务服务。
 *
 * <p>标记创建与复核均在单事务内完成，复用 request_log 幂等机制（同键同参重放首次结果、
 * 异参 409、失败不占键），并通过 observation_current 行锁与观测合并/删除串行化。
 *
 * <p>复核时若标记绑定版本已不是观测当前版本，事务整体回滚（不占幂等键），
 * 随后在独立事务中将该标记条件化地转 STALE，再向客户端返回 410。
 */
@Service
public class QualityFlagService {

    private static final String SEPARATOR = "";
    private static final int CONFIDENCE_DEDUCTION = 20;

    private final ObservationRepository observationRepository;
    private final QualityFlagRepository qualityFlagRepository;
    private final RequestLogRepository requestLogRepository;
    private final QualityFlagTransactions transactions;
    private final ObjectMapper objectMapper;

    public QualityFlagService(ObservationRepository observationRepository,
                              QualityFlagRepository qualityFlagRepository,
                              RequestLogRepository requestLogRepository,
                              QualityFlagTransactions transactions,
                              ObjectMapper objectMapper) {
        this.observationRepository = observationRepository;
        this.qualityFlagRepository = qualityFlagRepository;
        this.requestLogRepository = requestLogRepository;
        this.transactions = transactions;
        this.objectMapper = objectMapper;
    }

    /**
     * 写操作结果：HTTP 状态码与响应体。
     */
    public record FlagWriteOutcome(int status, Object body) {
    }

    /**
     * 创建待复核质量标记：附加于观测当前版本，不改变观测内容与版本。
     * flagKey 重复或同观测同类别已存在待复核标记时返回 409；观测已删除返回 410。
     */
    @Transactional
    public FlagWriteOutcome createFlag(String observationId, CreateQualityFlagRequest request) {
        String fingerprint = fingerprint("FLAG_CREATE", observationId, request.flagKey(),
                request.category().name(), request.description(), request.submittedBy());
        FlagWriteOutcome replayed = checkReplay(request.requestId(), fingerprint);
        if (replayed != null) {
            return replayed;
        }
        FlagWriteOutcome concurrent = insertPlaceholder(request.requestId(), fingerprint, "FLAG_CREATE");
        if (concurrent != null) {
            return concurrent;
        }

        // 对观测当前行加锁：与合并/删除/同观测其他标记写操作按事务提交顺序串行裁决
        ObservationSnapshot current = observationRepository.findCurrentForUpdate(observationId)
                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
        if (current.deleted()) {
            throw ApiException.gone("observation already deleted: " + observationId);
        }
        if (qualityFlagRepository.findByFlagKey(request.flagKey()).isPresent()) {
            throw ApiException.conflict("quality flag already exists: " + request.flagKey(), current.version());
        }
        if (qualityFlagRepository.existsPending(observationId, request.category())) {
            throw ApiException.conflict(
                    "pending quality flag already exists for category: " + request.category(), current.version());
        }

        QualityFlag flag = new QualityFlag(request.flagKey(), observationId, current.version(),
                request.category(), request.description(), request.submittedBy(), FlagStatus.PENDING,
                null, null, null, null, null);
        try {
            qualityFlagRepository.insert(flag);
        } catch (DuplicateKeyException e) {
            // 数据库唯一约束兜底：并发下同 flagKey 或同观测同类别 PENDING 竞争，后到者按冲突处理
            throw ApiException.conflict(
                    "duplicate quality flag key or pending flag of same category: " + request.flagKey(),
                    current.version());
        }
        QualityFlag stored = qualityFlagRepository.findByFlagKey(request.flagKey()).orElseThrow();
        QualityFlagResponse body = QualityFlagResponse.of(stored);
        return complete(request.requestId(), HttpStatus.CREATED, body);
    }

    /**
     * 复核质量标记：非事务编排入口。事务内发现版本不一致时回滚（失败不占键），
     * 再以独立事务把标记转 STALE 并返回 410。
     */
    public FlagWriteOutcome reviewFlag(String flagKey, ReviewQualityFlagRequest request) {
        try {
            return transactions.reviewInTransaction(flagKey, request);
        } catch (StaleFlagVersionException e) {
            // 主事务已回滚：独立事务条件化转 STALE（并发/重入幂等），随后返回 410
            transactions.markStaleInNewTransaction(flagKey);
            throw ApiException.gone(
                    "flag is no longer bound to the current observation version: " + flagKey,
                    e.currentVersion());
        }
    }

    /**
     * 查询某观测的全部质量标记（PENDING/CONFIRMED/DISMISSED/STALE），按创建顺序返回。
     */
    @Transactional(readOnly = true)
    public List<QualityFlagResponse> getFlagHistory(String observationId) {
        requireObservationExists(observationId);
        return qualityFlagRepository.findFlagsByObservation(observationId).stream()
                .map(QualityFlagResponse::newResponse)
                .toList();
    }

    /**
     * 查询某观测当前待复核标记清单。
     */
    @Transactional(readOnly = true)
    public List<QualityFlagResponse> getPendingFlags(String observationId) {
        requireObservationExists(observationId);
        return qualityFlagRepository.findPendingByObservation(observationId).stream()
                .map(QualityFlagResponse::newResponse)
                .toList();
    }

    /**
     * 查询某观测的置信度轨迹：初始 100、每次版本固化继承值、每次复核（含驳回与 0 扣减）按时间排列。
     */
    @Transactional(readOnly = true)
    public List<ConfidencePoint> getConfidenceTrail(String observationId) {
        List<VersionStamp> versions = observationRepository.findVersionStamps(observationId);
        if (versions.isEmpty()) {
            throw ApiException.notFound("observation not found: " + observationId);
        }
        List<QualityFlagReview> reviews = qualityFlagRepository.findReviewsByObservation(observationId);

        // 起点：版本 1 创建，初始置信度 100
        java.util.List<ConfidencePoint> points = new java.util.ArrayList<>();
        VersionStamp first = versions.get(0);
        points.add(new ConfidencePoint(first.version(), 100, ConfidenceEventType.INITIAL,
                null, null, null, first.createdAt()));

        // 版本固化点（v2 起）与复核事件点按发生时间归并；置信度在版本间延续，CONFIRMED 点取固化值
        java.util.List<ConfidencePoint> later = new java.util.ArrayList<>();
        for (int i = 1; i < versions.size(); i++) {
            VersionStamp stamp = versions.get(i);
            later.add(new ConfidencePoint(stamp.version(), -1, ConfidenceEventType.VERSION,
                    null, null, null, stamp.createdAt()));
        }
        for (QualityFlagReview review : reviews) {
            ConfidenceEventType type = review.conclusion() == ReviewConclusion.CONFIRMED
                    ? ConfidenceEventType.CONFIRMED : ConfidenceEventType.DISMISSED;
            later.add(new ConfidencePoint(review.flagVersion(), review.confidenceAfter(), type,
                    review.flagKey(), review.category(), review.confidenceDelta(), review.createdAt()));
        }
        later.sort(java.util.Comparator.comparing(ConfidencePoint::occurredAt));

        int currentConfidence = 100;
        for (ConfidencePoint point : later) {
            if (point.eventType() == ConfidenceEventType.VERSION) {
                // 新版本继承前一版本最终置信度并固化
                points.add(new ConfidencePoint(point.version(), currentConfidence,
                        ConfidenceEventType.VERSION, null, null, null, point.occurredAt()));
            } else {
                currentConfidence = point.confidence();
                points.add(point);
            }
        }
        return List.copyOf(points);
    }

    private void requireObservationExists(String observationId) {
        if (observationRepository.findCurrent(observationId).isEmpty()) {
            throw ApiException.notFound("observation not found: " + observationId);
        }
    }

    /**
     * 幂等检查：同键同参返回原成功结果；同键异参返回 409；无记录返回 null 继续执行。
     */
    private FlagWriteOutcome checkReplay(String requestId, String fingerprint) {
        Optional<RequestLogEntry> existing = requestLogRepository.find(requestId);
        if (existing.isEmpty()) {
            return null;
        }
        RequestLogEntry entry = existing.get();
        if (!entry.fingerprint().equals(fingerprint)) {
            throw ApiException.conflict("requestId reused with different parameters: " + requestId, null);
        }
        return new FlagWriteOutcome(entry.responseStatus(), readBody(entry.operation(), entry.responseBody()));
    }

    /**
     * 占位写入去重记录；并发同键时等待对方事务结束后重放或判异参 409；业务失败随事务回滚不占键。
     */
    private FlagWriteOutcome insertPlaceholder(String requestId, String fingerprint, String operation) {
        try {
            requestLogRepository.insertPlaceholder(requestId, fingerprint, operation);
            return null;
        } catch (DuplicateKeyException e) {
            RequestLogEntry entry = requestLogRepository.find(requestId)
                    .orElseThrow(() -> ApiException.conflict("requestId conflict: " + requestId, null));
            if (!entry.fingerprint().equals(fingerprint)) {
                throw ApiException.conflict("requestId reused with different parameters: " + requestId, null);
            }
            return new FlagWriteOutcome(entry.responseStatus(),
                    readBody(entry.operation(), entry.responseBody()));
        }
    }

    private FlagWriteOutcome complete(String requestId, HttpStatus status, Object body) {
        requestLogRepository.complete(requestId, status.value(), writeJson(body));
        return new FlagWriteOutcome(status.value(), body);
    }

    private String writeJson(Object body) {
        try {
            return objectMapper.writeValueAsString(body);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("failed to serialize response", e);
        }
    }

    private Object readBody(String operation, String json) {
        try {
            Class<?> type = "FLAG_REVIEW".equals(operation)
                    ? QualityFlagReviewResponse.class : QualityFlagResponse.class;
            return objectMapper.readValue(json, type);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("failed to deserialize stored response", e);
        }
    }

    private String fingerprint(String operation, String... parts) {
        StringBuilder raw = new StringBuilder(operation);
        for (String part : parts) {
            raw.append(SEPARATOR).append(part == null ? "<null>" : part);
        }
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(digest.digest(raw.toString().getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    /**
     * 质量标记复核的事务边界组件：复核主事务与 STALE 转换的独立事务分开管理，
     * 使“版本变化时返回 410 且标记转 STALE、失败不占幂等键”得以同时成立。
     */
    @Service
    public static class QualityFlagTransactions {

        private final ObservationRepository observationRepository;
        private final QualityFlagRepository qualityFlagRepository;
        private final RequestLogRepository requestLogRepository;

        QualityFlagTransactions(ObservationRepository observationRepository,
                                QualityFlagRepository qualityFlagRepository,
                                RequestLogRepository requestLogRepository) {
            this.observationRepository = observationRepository;
            this.qualityFlagRepository = qualityFlagRepository;
            this.requestLogRepository = requestLogRepository;
        }

        /**
         * 复核主事务。任何业务异常（含版本不一致）都会整体回滚，request_log 占位不占键。
         */
        @Transactional
        public FlagWriteOutcome reviewInTransaction(String flagKey, ReviewQualityFlagRequest request) {
            String fingerprint = new FingerprintBuilder("FLAG_REVIEW")
                    .add(flagKey).add(request.conclusion().name()).add(request.reason())
                    .add(request.reviewedBy()).build();
            FlagWriteOutcome replayed = checkReplay(request.requestId(), fingerprint);
            if (replayed != null) {
                return replayed;
            }
            FlagWriteOutcome concurrent = insertPlaceholder(request.requestId(), fingerprint, "FLAG_REVIEW");
            if (concurrent != null) {
                return concurrent;
            }

            // 先锁标记行：串行化同一标记的并发复核
            QualityFlag flag = qualityFlagRepository.findByFlagKeyForUpdate(flagKey)
                    .orElseThrow(() -> ApiException.notFound("quality flag not found: " + flagKey));
            switch (flag.status()) {
                case CONFIRMED, DISMISSED -> throw ApiException.conflict(
                        "quality flag already reviewed: " + flagKey, flag.version());
                case STALE -> throw ApiException.gone(
                        "quality flag is stale: " + flagKey, flag.version());
                default -> {
                    // PENDING：继续校验
                }
            }
            if (request.reviewedBy().equals(flag.submittedBy())) {
                throw ApiException.forbidden(
                        "reviewer must differ from the submitting role: " + request.reviewedBy());
            }

            // 再锁观测当前行：与合并/删除按提交顺序串行；复核必须基于一致的版本状态
            ObservationSnapshot current = observationRepository.findCurrentForUpdate(flag.observationId())
                    .orElseThrow(() -> new StaleFlagVersionException(flagKey, flag.version()));
            if (current.deleted() || current.version() != flag.version()) {
                // 观测已产生新版本（含删除墓碑）：回滚本事务，由外层转 STALE 并返回 410
                throw new StaleFlagVersionException(flagKey, current.version());
            }

            boolean deduct = request.conclusion() == ReviewConclusion.CONFIRMED
                    && !qualityFlagRepository.existsEffectiveDeduction(
                            flag.observationId(), flag.version(), flag.category());
            int confidenceAfter = current.confidence();
            int delta = 0;
            if (deduct) {
                delta = -CONFIDENCE_DEDUCTION;
                confidenceAfter = Math.max(0, current.confidence() + delta);
            }

            FlagStatus finalStatus = request.conclusion() == ReviewConclusion.CONFIRMED
                    ? FlagStatus.CONFIRMED : FlagStatus.DISMISSED;
            qualityFlagRepository.completeReview(flagKey, finalStatus, request.reviewedBy(),
                    request.reason(), flag.version());
            qualityFlagRepository.insertReview(new QualityFlagReview(
                    null, flagKey, flag.observationId(), flag.version(), flag.version(), flag.category(),
                    request.conclusion(), request.reason(), request.reviewedBy(),
                    confidenceAfter, delta, null));
            if (deduct) {
                // 只改当前版本：更新当前状态并固化当前版本快照；更早历史快照永不改写
                observationRepository.updateConfidence(flag.observationId(), confidenceAfter);
                observationRepository.updateVersionConfidence(
                        flag.observationId(), flag.version(), confidenceAfter);
            }

            QualityFlag stored = qualityFlagRepository.findByFlagKey(flagKey).orElseThrow();
            QualityFlagReviewResponse body = new QualityFlagReviewResponse(
                    flagKey, flag.observationId(), flag.version(), flag.version(),
                    request.conclusion(), request.reason(), request.reviewedBy(),
                    confidenceAfter, deduct, stored.reviewedAt());
            requestLogRepository.complete(request.requestId(), HttpStatus.OK.value(),
                    new JsonBodyWriter().write(body));
            return new FlagWriteOutcome(HttpStatus.OK.value(), body);
        }

        /**
         * 在全新独立事务中条件化地把仍为 PENDING 的标记转 STALE；
         * 与主事务的回滚结果解耦，并发/重入调用幂等。
         */
        @Transactional(propagation = Propagation.REQUIRES_NEW)
        public void markStaleInNewTransaction(String flagKey) {
            qualityFlagRepository.markStaleIfPending(flagKey);
        }

        private FlagWriteOutcome checkReplay(String requestId, String fingerprint) {
            Optional<RequestLogEntry> existing = requestLogRepository.find(requestId);
            if (existing.isEmpty()) {
                return null;
            }
            RequestLogEntry entry = existing.get();
            if (!entry.fingerprint().equals(fingerprint)) {
                throw ApiException.conflict("requestId reused with different parameters: " + requestId, null);
            }
            return new FlagWriteOutcome(entry.responseStatus(),
                    new JsonBodyWriter().read(entry.responseBody(),
                            "FLAG_REVIEW".equals(entry.operation())
                                    ? QualityFlagReviewResponse.class : QualityFlagResponse.class));
        }

        private FlagWriteOutcome insertPlaceholder(String requestId, String fingerprint, String operation) {
            try {
                requestLogRepository.insertPlaceholder(requestId, fingerprint, operation);
                return null;
            } catch (DuplicateKeyException e) {
                RequestLogEntry entry = requestLogRepository.find(requestId)
                        .orElseThrow(() -> ApiException.conflict("requestId conflict: " + requestId, null));
                if (!entry.fingerprint().equals(fingerprint)) {
                    throw ApiException.conflict(
                            "requestId reused with different parameters: " + requestId, null);
                }
                return new FlagWriteOutcome(entry.responseStatus(),
                        new JsonBodyWriter().read(entry.responseBody(),
                                "FLAG_REVIEW".equals(entry.operation())
                                        ? QualityFlagReviewResponse.class : QualityFlagResponse.class));
            }
        }
    }

    /**
     * 指纹构造器（内部事务组件静态使用，避免对外暴露服务私有方法）。
     */
    private static final class FingerprintBuilder {
        private final StringBuilder raw;

        private FingerprintBuilder(String operation) {
            this.raw = new StringBuilder(operation);
        }

        private FingerprintBuilder add(String part) {
            raw.append(SEPARATOR).append(part == null ? "<null>" : part);
            return this;
        }

        private String build() {
            try {
                MessageDigest digest = MessageDigest.getInstance("SHA-256");
                return HexFormat.of().formatHex(digest.digest(raw.toString().getBytes(StandardCharsets.UTF_8)));
            } catch (NoSuchAlgorithmException e) {
                throw new IllegalStateException("SHA-256 not available", e);
            }
        }
    }

    /**
     * JSON 读写小工具（内部事务组件使用同一 Spring 容器中的 ObjectMapper 由调用方传入代价较大，
     * 此处直接构造与主服务一致配置的 mapper 仅用于已落库响应体的 round-trip）。
     */
    private static final class JsonBodyWriter {
        private final ObjectMapper mapper = new ObjectMapper();

        private String write(Object body) {
            try {
                return mapper.writeValueAsString(body);
            } catch (JsonProcessingException e) {
                throw new IllegalStateException("failed to serialize response", e);
            }
        }

        private Object read(String json, Class<?> type) {
            try {
                return mapper.readValue(json, type);
            } catch (JsonProcessingException e) {
                throw new IllegalStateException("failed to deserialize stored response", e);
            }
        }
    }
}

