    /**
     * 占位写入去重记录；并发同键时等待对方事务结束后重放或判异参 409；业务失败随事务回滚不占键。
     */
    private FlagWriteOutcome insertPlaceholder(String requestId, String fingerprint, String operation) {
        try {
            requestLogRepository.insertPlaceholder(requestId, fingerprint, operation);
            return null;
        } catch (DuplicateKeyException e) {
            RequestLogEntry entry = requestLogRepository.find(requestId)
                    .orElseThrow(() -> ApiException.conflict("requestId conflict: " + requestId, null));
            if (!entry.fingerprint().equals(fingerprint)) {
                throw ApiException.conflict("requestId reused with different parameters: " + requestId, null);
            }
            return new FlagWriteOutcome(entry.responseStatus(),
                    readBody(entry.operation(), entry.responseBody()));
        }
    }

    private FlagWriteOutcome complete(String requestId, HttpStatus status, Object body) {
        requestLogRepository.complete(requestId, status.value(), writeJson(body));
        return new FlagWriteOutcome(status.value(), body);
    }

    private String writeJson(Object body) {
        try {
            return objectMapper.writeValueAsString(body);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("failed to serialize response", e);
        }
    }

    private Object readBody(String operation, String json) {
        try {
            Class<?> type = "FLAG_REVIEW".equals(operation)
                    ? QualityFlagReviewResponse.class : QualityFlagResponse.class;
            return objectMapper.readValue(json, type);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("failed to deserialize stored response", e);
        }
    }

    private String fingerprint(String operation, String... parts) {
        StringBuilder raw = new StringBuilder(operation);
        for (String part : parts) {
            raw.append(SEPARATOR).append(part == null ? "<null>" : part);
        }
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(digest.digest(raw.toString().getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    /**
     * 质量标记复核的事务边界组件：复核主事务与 STALE 转换的独立事务分开管理，
     * 使“版本变化时返回 410 且标记转 STALE、失败不占幂等键”得以同时成立。
     */
    @Service
    public static class QualityFlagTransactions {

        private final ObservationRepository observationRepository;
        private final QualityFlagRepository qualityFlagRepository;
        private final RequestLogRepository requestLogRepository;

        QualityFlagTransactions(ObservationRepository observationRepository,
                                QualityFlagRepository qualityFlagRepository,
                                RequestLogRepository requestLogRepository) {
            this.observationRepository = observationRepository;
            this.qualityFlagRepository = qualityFlagRepository;
            this.requestLogRepository = requestLogRepository;
        }

        /**
         * 复核主事务。任何业务异常（含版本不一致）都会整体回滚，request_log 占位不占键。
         */
        @Transactional
        public FlagWriteOutcome reviewInTransaction(String flagKey, ReviewQualityFlagRequest request) {
            String fingerprint = new FingerprintBuilder("FLAG_REVIEW")
                    .add(flagKey).add(request.conclusion().name()).add(request.reason())
                    .add(request.reviewedBy()).build();
            FlagWriteOutcome replayed = checkReplay(request.requestId(), fingerprint);
            if (replayed != null) {
                return replayed;
            }
            FlagWriteOutcome concurrent = insertPlaceholder(request.requestId(), fingerprint, "FLAG_REVIEW");
            if (concurrent != null) {
                return concurrent;
            }

            // 先锁标记行：串行化同一标记的并发复核
            QualityFlag flag = qualityFlagRepository.findByFlagKeyForUpdate(flagKey)
                    .orElseThrow(() -> ApiException.notFound("quality flag not found: " + flagKey));
            switch (flag.status()) {
                case CONFIRMED, DISMISSED -> throw ApiException.conflict(
                        "quality flag already reviewed: " + flagKey, flag.version());
                case STALE -> throw ApiException.gone(
                        "quality flag is stale: " + flagKey, flag.version());
                default -> {
                    // PENDING：继续校验
                }
            }
            if (request.reviewedBy().equals(flag.submittedBy())) {
                throw ApiException.forbidden(
                        "reviewer must differ from the submitting role: " + request.reviewedBy());
            }

            // 再锁观测当前行：与合并/删除按提交顺序串行；复核必须基于一致的版本状态
            ObservationSnapshot current = observationRepository.findCurrentForUpdate(flag.observationId())
                    .orElseThrow(() -> new StaleFlagVersionException(flagKey, flag.version()));
            if (current.deleted() || current.version() != flag.version()) {
                // 观测已产生新版本（含删除墓碑）：回滚本事务，由外层转 STALE 并返回 410
                throw new StaleFlagVersionException(flagKey, current.version());
            }

            boolean deduct = request.conclusion() == ReviewConclusion.CONFIRMED
                    && !qualityFlagRepository.existsEffectiveDeduction(
                            flag.observationId(), flag.version(), flag.category());
            int confidenceAfter = current.confidence();
            int delta = 0;
            if (deduct) {
                delta = -CONFIDENCE_DEDUCTION;
                confidenceAfter = Math.max(0, current.confidence() + delta);
            }

            FlagStatus finalStatus = request.conclusion() == ReviewConclusion.CONFIRMED
                    ? FlagStatus.CONFIRMED : FlagStatus.DISMISSED;
            qualityFlagRepository.completeReview(flagKey, finalStatus, request.reviewedBy(),
                    request.reason(), flag.version());
            qualityFlagRepository.insertReview(new QualityFlagReview(
                    null, flagKey, flag.observationId(), flag.version(), flag.version(), flag.category(),
                    request.conclusion(), request.reason(), request.reviewedBy(),
                    confidenceAfter, delta, null));
            if (deduct) {
                // 只改当前版本：更新当前状态并固化当前版本快照；更早历史快照永不改写
                observationRepository.updateConfidence(flag.observationId(), confidenceAfter);
                observationRepository.updateVersionConfidence(
                        flag.observationId(), flag.version(), confidenceAfter);
            }

            QualityFlag stored = qualityFlagRepository.findByFlagKey(flagKey).orElseThrow();
            QualityFlagReviewResponse body = new QualityFlagReviewResponse(
                    flagKey, flag.observationId(), flag.version(), flag.version(),
                    request.conclusion(), request.reason(), request.reviewedBy(),
                    confidenceAfter, deduct, stored.reviewedAt());
            requestLogRepository.complete(request.requestId(), HttpStatus.OK.value(),
                    new JsonBodyWriter().write(body));
            return new FlagWriteOutcome(HttpStatus.OK.value(), body);
        }

        /**
         * 在全新独立事务中条件化地把仍为 PENDING 的标记转 STALE；
         * 与主事务的回滚结果解耦，并发/重入调用幂等。
         */
        @Transactional(propagation = Propagation.REQUIRES_NEW)
        public void markStaleInNewTransaction(String flagKey) {
            qualityFlagRepository.markStaleIfPending(flagKey);
        }

        private FlagWriteOutcome checkReplay(String requestId, String fingerprint) {
            Optional<RequestLogEntry> existing = requestLogRepository.find(requestId);
            if (existing.isEmpty()) {
                return null;
            }
            RequestLogEntry entry = existing.get();
            if (!entry.fingerprint().equals(fingerprint)) {
                throw ApiException.conflict("requestId reused with different parameters: " + requestId, null);
            }
            return new FlagWriteOutcome(entry.responseStatus(),
                    new JsonBodyWriter().read(entry.responseBody(),
                            "FLAG_REVIEW".equals(entry.operation())
                                    ? QualityFlagReviewResponse.class : QualityFlagResponse.class));
        }

        private FlagWriteOutcome insertPlaceholder(String requestId, String fingerprint, String operation) {
            try {
                requestLogRepository.insertPlaceholder(requestId, fingerprint, operation);
                return null;
            } catch (DuplicateKeyException e) {
                RequestLogEntry entry = requestLogRepository.find(requestId)
                        .orElseThrow(() -> ApiException.conflict("requestId conflict: " + requestId, null));
                if (!entry.fingerprint().equals(fingerprint)) {
                    throw ApiException.conflict(
                            "requestId reused with different parameters: " + requestId, null);
                }
                return new FlagWriteOutcome(entry.responseStatus(),
                        new JsonBodyWriter().read(entry.responseBody(),
                                "FLAG_REVIEW".equals(entry.operation())
                                        ? QualityFlagReviewResponse.class : QualityFlagResponse.class));
            }
        }
    }

    /**
     * 指纹构造器（内部事务组件静态使用，避免对外暴露服务私有方法）。
     */
    private static final class FingerprintBuilder {
        private final StringBuilder raw;

        private FingerprintBuilder(String operation) {
            this.raw = new StringBuilder(operation);
        }

        private FingerprintBuilder add(String part) {
            raw.append(SEPARATOR).append(part == null ? "<null>" : part);
            return this;
        }

        private String build() {
            try {
                MessageDigest digest = MessageDigest.getInstance("SHA-256");
                return HexFormat.of().formatHex(digest.digest(raw.toString().getBytes(StandardCharsets.UTF_8)));
            } catch (NoSuchAlgorithmException e) {
                throw new IllegalStateException("SHA-256 not available", e);
            }
        }
    }

    /**
     * JSON 读写小工具（内部事务组件使用同一 Spring 容器中的 ObjectMapper 由调用方传入代价较大，
     * 此处直接构造与主服务一致配置的 mapper 仅用于已落库响应体的 round-trip）。
     */
    private static final class JsonBodyWriter {
        private final ObjectMapper mapper = new ObjectMapper();

        private String write(Object body) {
            try {
                return mapper.writeValueAsString(body);
            } catch (JsonProcessingException e) {
                throw new IllegalStateException("failed to serialize response", e);
            }
        }

        private Object read(String json, Class<?> type) {
            try {
                return mapper.readValue(json, type);
            } catch (JsonProcessingException e) {
                throw new IllegalStateException("failed to deserialize stored response", e);
            }
        }
    }
}

