package com.example.starter.observation;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

import java.util.List;
import java.util.Optional;

/**
 * 质量标记与复核记录持久化：维护 quality_flag 标记状态与 quality_flag_review 不可变复核记录。
 * 同观测同类别唯一 PENDING 由 pending_dedup_key 唯一索引在数据库层裁决。
 * 所有 SQL 使用参数化查询。
 */
@Repository
public class QualityFlagRepository {

    private static final String FLAG_COLUMNS =
            "flag_key, observation_id, version, category, description, submitted_by, status, "
                    + "pending_dedup_key, reviewed_by, review_reason, review_version, created_at, reviewed_at";

    private static final RowMapper<QualityFlag> FLAG_MAPPER = (rs, rowNum) -> new QualityFlag(
            rs.getString("flag_key"),
            rs.getString("observation_id"),
            rs.getInt("version"),
            QualityCategory.valueOf(rs.getString("category")),
            rs.getString("description"),
            rs.getString("submitted_by"),
            FlagStatus.valueOf(rs.getString("status")),
            rs.getString("reviewed_by"),
            rs.getString("review_reason"),
            (Integer) rs.getObject("review_version"),
            rs.getTimestamp("created_at").toLocalDateTime(),
            rs.getTimestamp("reviewed_at") == null ? null : rs.getTimestamp("reviewed_at").toLocalDateTime());

    private static final RowMapper<QualityFlagReview> REVIEW_MAPPER = (rs, rowNum) -> new QualityFlagReview(
            rs.getLong("id"),
            rs.getString("flag_key"),
            rs.getString("observation_id"),
            rs.getInt("flag_version"),
            rs.getInt("review_version"),
            QualityCategory.valueOf(rs.getString("category")),
            ReviewConclusion.valueOf(rs.getString("conclusion")),
            rs.getString("reason"),
            rs.getString("reviewed_by"),
            rs.getInt("confidence_after"),
            rs.getInt("confidence_delta"),
            rs.getTimestamp("created_at").toLocalDateTime());

    private final JdbcTemplate jdbcTemplate;

    public QualityFlagRepository(JdbcTemplate jdbcTemplate) {
        this.jdbcTemplate = jdbcTemplate;
    }

    /**
     * 插入待复核标记并写入待复核去重键（observationId#category）；
     * flagKey 主键冲突或同观测同类别已有 PENDING（去重键冲突）均抛 DuplicateKeyException，由上层裁决。
     */
    public void insert(QualityFlag flag) {
        jdbcTemplate.update(
                "INSERT INTO quality_flag (flag_key, observation_id, version, category, description, "
                        + "submitted_by, status, pending_dedup_key, reviewed_by, review_reason, "
                        + "review_version, created_at, reviewed_at) "
                        + "VALUES (?, ?, ?, ?, ?, ?, 'PENDING', ?, NULL, NULL, NULL, CURRENT_TIMESTAMP, NULL)",
                flag.flagKey(), flag.observationId(), flag.version(), flag.category().name(),
                flag.description(), flag.submittedBy(), pendingDedupKey(flag.observationId(), flag.category()));
    }

    /**
     * 按 flagKey 读取标记（不加锁），用于查询接口。
     */
    public Optional<QualityFlag> findByFlagKey(String flagKey) {
        return jdbcTemplate.query(flagSelect() + " WHERE flag_key = ?", FLAG_MAPPER, flagKey)
                .stream().findFirst();
    }

    /**
     * 按 flagKey 读取标记并加行锁，用于复核事务内串行化对同一标记的并发操作。
     */
    public Optional<QualityFlag> findByFlagKeyForUpdate(String flagKey) {
        return jdbcTemplate.query(flagSelect() + " WHERE flag_key = ? FOR UPDATE", FLAG_MAPPER, flagKey)
                .stream().findFirst();
    }

    /**
     * 复核成功：状态置为终态、清空待复核去重键（允许该类别再次提交新标记），固化复核信息。
     */
    public void completeReview(String flagKey, FlagStatus status, String reviewedBy, String reason,
                               int reviewVersion) {
        jdbcTemplate.update(
                "UPDATE quality_flag SET status = ?, pending_dedup_key = NULL, reviewed_by = ?, "
                        + "review_reason = ?, review_version = ?, reviewed_at = CURRENT_TIMESTAMP "
                        + "WHERE flag_key = ?",
                status.name(), reviewedBy, reason, reviewVersion, flagKey);
    }

    /**
     * 观测产生新版本（合并或删除墓碑）时，在同一事务内把绑定旧版本的全部待复核标记
     * 主动转为 STALE 并清空待复核去重键：它们不再可复核，也不影响新版本；
     * 同时释放同类别去重位，使新版本上可以再次提交该类别标记。
     */
    public int stalePendingFlagsForVersion(String observationId, int version) {
        return jdbcTemplate.update(
                "UPDATE quality_flag SET status = 'STALE', pending_dedup_key = NULL "
                        + "WHERE observation_id = ? AND version = ? AND status = 'PENDING'",
                observationId, version);
    }

    /**
     * 版本已变化：条件化地把仍处于 PENDING 的标记转 STALE 并清空待复核去重键。
     * 仅 PENDING 行受影响，保证并发/重入调用幂等；STALE 不是复核，不写复核信息与 reviewed_at。
     *
     * @return 实际被更新的行数（1 表示本次完成转换，0 表示标记已不在 PENDING）
     */
    public int markStaleIfPending(String flagKey) {
        return jdbcTemplate.update(
                "UPDATE quality_flag SET status = 'STALE', pending_dedup_key = NULL "
                        + "WHERE flag_key = ? AND status = 'PENDING'",
                flagKey);
    }

    /**
     * 追加不可变复核记录，固化类别与置信度变化。
     */
    public void insertReview(QualityFlagReview review) {
        jdbcTemplate.update(
                "INSERT INTO quality_flag_review (flag_key, observation_id, flag_version, review_version, "
                        + "category, conclusion, reason, reviewed_by, confidence_after, confidence_delta, created_at) "
                        + "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP)",
                review.flagKey(), review.observationId(), review.flagVersion(), review.reviewVersion(),
                review.category().name(), review.conclusion().name(), review.reason(), review.reviewedBy(),
                review.confidenceAfter(), review.confidenceDelta());
    }

    /**
     * 同一观测同一类别当前是否存在待复核标记（预检；并发正确性由 pending_dedup_key 唯一索引兜底）。
     */
    public boolean existsPending(String observationId, QualityCategory category) {
        Integer count = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM quality_flag "
                        + "WHERE observation_id = ? AND category = ? AND status = 'PENDING'",
                Integer.class, observationId, category.name());
        return count != null && count > 0;
    }

    /**
     * 同一观测同一版本同一类别是否已存在产生实际扣减的有效 CONFIRMED 复核。
     * 同版本同类别第二个 CONFIRMED 不再扣减；新版本（version 不同）不受影响。
     */
    public boolean existsEffectiveDeduction(String observationId, int version, QualityCategory category) {
        Integer count = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM quality_flag_review "
                        + "WHERE observation_id = ? AND flag_version = ? AND category = ? "
                        + "AND conclusion = 'CONFIRMED' AND confidence_delta < 0",
                Integer.class, observationId, version, category.name());
        return count != null && count > 0;
    }

    /**
     * 查询某观测的全部标记（含各状态），按创建顺序返回。
     */
    public List<QualityFlag> findFlagsByObservation(String observationId) {
        return jdbcTemplate.query(
                flagSelect() + " WHERE observation_id = ? ORDER BY created_at, flag_key",
                FLAG_MAPPER, observationId);
    }

    /**
     * 查询某观测当前待复核标记清单。绑定旧版本的标记在版本产生时已主动转 STALE，
     * 因此 PENDING 标记必然仍绑定当前版本。
     */
    public List<QualityFlag> findPendingByObservation(String observationId) {
        return jdbcTemplate.query(
                flagSelect() + " WHERE observation_id = ? AND status = 'PENDING' "
                        + "ORDER BY created_at, flag_key",
                FLAG_MAPPER, observationId);
    }

    /**
     * 查询某观测的全部不可变复核记录，按写入顺序返回。
     */
    public List<QualityFlagReview> findReviewsByObservation(String observationId) {
        return jdbcTemplate.query(
                "SELECT id, flag_key, observation_id, flag_version, review_version, category, conclusion, "
                        + "reason, reviewed_by, confidence_after, confidence_delta, created_at "
                        + "FROM quality_flag_review WHERE observation_id = ? ORDER BY id",
                REVIEW_MAPPER, observationId);
    }

    /**
     * 待复核去重键：观测标识与类别用分隔符拼接（分隔符不出现在类别枚举中）。
     */
    public static String pendingDedupKey(String observationId, QualityCategory category) {
        return observationId + "#" + category.name();
    }

    private String flagSelect() {
        return "SELECT " + FLAG_COLUMNS + " FROM quality_flag";
    }
}

package com.example.starter.observation;

import org.springframework.dao.DuplicateKeyException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.ArrayList;
import java.util.List;

/**
 * 观测质量标记业务服务。
 *
 * <p>标记创建在单事务内完成，复用 request_log 幂等机制（同键同参重放首次结果、异参 409、
 * 失败不占键），并通过 observation_current 行锁与观测合并/删除按事务提交顺序串行裁决。
 *
 * <p>复核由 {@link ReviewTransactionRunner} 承担事务边界：事务内若发现标记绑定版本已不是
 * 观测当前版本则整体回滚（不占幂等键），本服务捕获后在独立事务把标记条件化转 STALE，再返回 410。
 *
 * <p>置信度规则：初始 100；同版本每个不同类别的首个有效 CONFIRMED 扣减 20，最低 0；
 * DISMISSED 不影响；同版本同类别重复 CONFIRMED 不重复扣减，需合并产生新版本后该类别才能再次扣减；
 * 置信度随版本固化在各历史快照中，一旦确定不再被后续版本改写。
 */
@Service
public class QualityFlagService {

    private final ObservationRepository observationRepository;
    private final QualityFlagRepository qualityFlagRepository;
    private final ReviewTransactionRunner reviewTransactionRunner;
    private final FlagIdempotency idempotency;

    public QualityFlagService(ObservationRepository observationRepository,
                              QualityFlagRepository qualityFlagRepository,
                              ReviewTransactionRunner reviewTransactionRunner,
                              FlagIdempotency idempotency) {
        this.observationRepository = observationRepository;
        this.qualityFlagRepository = qualityFlagRepository;
        this.reviewTransactionRunner = reviewTransactionRunner;
        this.idempotency = idempotency;
    }

    /**
     * 写操作结果：HTTP 状态码与响应体。
     */
    public record FlagWriteOutcome(int status, Object body) {
    }

    /**
     * 创建待复核质量标记：附加于观测当前版本，不改变观测内容与版本。
     * flagKey 重复或同观测同类别已存在待复核标记返回 409；观测不存在 404；观测已删除 410。
     */
    @Transactional
    public FlagWriteOutcome createFlag(String observationId, CreateQualityFlagRequest request) {
        String fingerprint = idempotency.fingerprint("FLAG_CREATE", observationId, request.flagKey(),
                request.category().name(), request.description(), request.submittedBy());
        FlagIdempotency.Outcome replayed = idempotency.checkReplay(request.requestId(), fingerprint);
        if (replayed != null) {
            return new FlagWriteOutcome(replayed.status(), replayed.body());
        }
        FlagIdempotency.Outcome concurrent = idempotency.insertPlaceholder(
                request.requestId(), fingerprint, "FLAG_CREATE");
        if (concurrent != null) {
            return new FlagWriteOutcome(concurrent.status(), concurrent.body());
        }

        // 锁观测当前行：与合并/删除/同观测其他标记写操作按事务提交顺序串行裁决
        ObservationSnapshot current = observationRepository.findCurrentForUpdate(observationId)
                .orElseThrow(() -> ApiException.notFound("observation not found: " + observationId));
        if (current.deleted()) {
            throw ApiException.gone("observation already deleted: " + observationId);
        }
        if (qualityFlagRepository.findByFlagKey(request.flagKey()).isPresent()) {
            throw ApiException.conflict("quality flag already exists: " + request.flagKey(), current.version());
        }
        if (qualityFlagRepository.existsPending(observationId, request.category())) {
            throw ApiException.conflict(
                    "pending quality flag already exists for category: " + request.category(),
                    current.version());
        }

        QualityFlag flag = new QualityFlag(request.flagKey(), observationId, current.version(),
                request.category(), request.description(), request.submittedBy(), FlagStatus.PENDING,
                null, null, null, null, null);
        try {
            qualityFlagRepository.insert(flag);
        } catch (DuplicateKeyException e) {
            // 唯一约束兜底：并发下同 flagKey 或同观测同类别 PENDING 竞争，后到者 409
            throw ApiException.conflict(
                    "duplicate quality flag key or pending flag of same category: " + request.flagKey(),
                    current.version());
        }
        QualityFlag stored = qualityFlagRepository.findByFlagKey(request.flagKey()).orElseThrow();
        FlagIdempotency.Outcome done = idempotency.complete(request.requestId(),
                HttpStatus.CREATED.value(), QualityFlagResponse.of(stored));
        return new FlagWriteOutcome(done.status(), done.body());
    }

    /**
     * 复核质量标记（非事务编排入口）。版本不一致时主事务回滚，再独立转 STALE 并返回 410。
     */
    public FlagWriteOutcome reviewFlag(String flagKey, ReviewQualityFlagRequest request) {
        try {
            FlagIdempotency.Outcome outcome = reviewTransactionRunner.reviewInTransaction(flagKey, request);
            return new FlagWriteOutcome(outcome.status(), outcome.body());
        } catch (StaleFlagVersionException e) {
            // 主事务已回滚、不占幂等键：独立事务条件化转 STALE，再返回 410
            reviewTransactionRunner.markStaleInNewTransaction(flagKey);
            throw ApiException.gone(
                    "flag is no longer bound to the current observation version: " + flagKey,
                    e.currentVersion());
        }
    }

    /**
     * 查询某观测的全部质量标记（PENDING/CONFIRMED/DISMISSED/STALE），按创建顺序返回。
     */
    @Transactional(readOnly = true)
    public List<QualityFlagResponse> getFlagHistory(String observationId) {
        requireObservationExists(observationId);
        return qualityFlagRepository.findFlagsByObservation(observationId).stream()
                .map(QualityFlagResponse::of)
                .toList();
    }

    /**
     * 查询某观测当前待复核标记清单（仅绑定当前版本、状态 PENDING 的标记）。
     */
    @Transactional(readOnly = true)
    public List<QualityFlagResponse> getPendingFlags(String observationId) {
        requireObservationExists(observationId);
        return qualityFlagRepository.findPendingByObservation(observationId).stream()
                .map(QualityFlagResponse::of)
                .toList();
    }

    /**
     * 查询某观测的置信度轨迹。
     *
     * <p>按版本分段全序归并：版本 1 为 INITIAL(100)；其后每个版本先有 VERSION 点（继承上一版本
     * 最终置信度），版本段内按复核记录写入顺序追加 CONFIRMED/DISMISSED 点。不依赖时间戳相等性，
     * 同事务内连续事件也能确定排序。
     */
    @Transactional(readOnly = true)
    public List<ConfidencePoint> getConfidenceTrail(String observationId) {
        List<VersionStamp> versions = observationRepository.findVersionStamps(observationId);
        if (versions.isEmpty()) {
            throw ApiException.notFound("observation not found: " + observationId);
        }
        List<QualityFlagReview> reviews = qualityFlagRepository.findReviewsByObservation(observationId);

        List<ConfidencePoint> points = new ArrayList<>();
        VersionStamp first = versions.get(0);
        points.add(new ConfidencePoint(first.version(), 100, ConfidenceEventType.INITIAL,
                null, null, null, first.createdAt()));

        int runningConfidence = 100;
        for (int i = 0; i < versions.size(); i++) {
            int version = versions.get(i).version();
            if (i > 0) {
                // 新版本生成时刻继承上一版本最终置信度并固化
                points.add(new ConfidencePoint(version, runningConfidence, ConfidenceEventType.VERSION,
                        null, null, null, versions.get(i).createdAt()));
            }
            // findReviewsByObservation 按自增 id 升序，天然给出同版本段内的复核先后顺序
            for (QualityFlagReview review : reviews) {
                if (review.flagVersion() != version) {
                    continue;
                }
                ConfidenceEventType type = review.conclusion() == ReviewConclusion.CONFIRMED
                        ? ConfidenceEventType.CONFIRMED : ConfidenceEventType.DISMISSED;
                points.add(new ConfidencePoint(version, review.confidenceAfter(), type,
                        review.flagKey(), review.category(), review.confidenceDelta(), review.createdAt()));
                runningConfidence = review.confidenceAfter();
            }
        }
        return List.copyOf(points);
    }

    private void requireObservationExists(String observationId) {
        if (observationRepository.findCurrent(observationId).isEmpty()) {
            throw ApiException.notFound("observation not found: " + observationId);
        }
    }
}

